#define SW_RawEthernetMessage_DIM_0 1600

typedef uint8_t SW_RawEthernetMessage [SW_RawEthernetMessage_DIM_0];

#define SW_RawEthernetMessage_BYTE_SIZE (sizeof(SW_RawEthernetMessage))

_Static_assert(sizeof(SW_RawEthernetMessage) == 1600, "SW_RawEthernetMessage: memory layout differs from HAMR's");
_Static_assert(_Alignof(SW_RawEthernetMessage) == 1, "SW_RawEthernetMessage: memory layout differs from HAMR's");


static inline bool SW_RawEthernetMessage_is_valid(const SW_RawEthernetMessage *v) {
  for (size_t i = 0; i < SW_RawEthernetMessage_DIM_0; i++) {
    if (!uint8_t_is_valid(&(*v)[i])) {
      return false;
    }
  }
  return true;
}

typedef struct SW_StructuredEthernetMessage_i {
  bool malformedFrame;
  SW_InternetProtocol internetProtocol;
  SW_FrameProtocol frameProtocol;
  bool portIsWhitelisted;
  SW_ARP_Type arpType;
  SW_RawEthernetMessage rawMessage;
} SW_StructuredEthernetMessage_i;

_Static_assert(sizeof(SW_StructuredEthernetMessage_i) == 1620, "SW_StructuredEthernetMessage_i: memory layout differs from HAMR's");
_Static_assert(_Alignof(SW_StructuredEthernetMessage_i) == 4, "SW_StructuredEthernetMessage_i: memory layout differs from HAMR's");
_Static_assert(offsetof(SW_StructuredEthernetMessage_i, malformedFrame) == 0, "SW_StructuredEthernetMessage_i: memory layout differs from HAMR's");
_Static_assert(offsetof(SW_StructuredEthernetMessage_i, internetProtocol) == 4, "SW_StructuredEthernetMessage_i: memory layout differs from HAMR's");
_Static_assert(offsetof(SW_StructuredEthernetMessage_i, frameProtocol) == 8, "SW_StructuredEthernetMessage_i: memory layout differs from HAMR's");
_Static_assert(offsetof(SW_StructuredEthernetMessage_i, portIsWhitelisted) == 12, "SW_StructuredEthernetMessage_i: memory layout differs from HAMR's");
_Static_assert(offsetof(SW_StructuredEthernetMessage_i, arpType) == 16, "SW_StructuredEthernetMessage_i: memory layout differs from HAMR's");
_Static_assert(offsetof(SW_StructuredEthernetMessage_i, rawMessage) == 20, "SW_StructuredEthernetMessage_i: memory layout differs from HAMR's");

static inline bool SW_StructuredEthernetMessage_i_is_valid(const SW_StructuredEthernetMessage_i *v) {
  return bool_is_valid(&v->malformedFrame) &&
                  SW_InternetProtocol_is_valid(&v->internetProtocol) &&
                  SW_FrameProtocol_is_valid(&v->frameProtocol) &&
                  bool_is_valid(&v->portIsWhitelisted) &&
                  SW_ARP_Type_is_valid(&v->arpType) &&
                  SW_RawEthernetMessage_is_valid(&v->rawMessage);
}
